// Mesma estrategia do Qualificador: ponto unico de parsing.
const bruto = $input.first().json.output ?? '';
const limpo = String(bruto).replace(/```json|```/g, '').trim();
const inicio = limpo.indexOf('{');
const fim = limpo.lastIndexOf('}');

let dados;
try {
  dados = JSON.parse(limpo.slice(inicio, fim + 1));
} catch (e) {
  dados = {
    cliente: null, categoria: 'tecnico', urgencia: 'media',
    sla_horas: 24, tier_cliente: null,
    descricao: 'Falha ao estruturar o chamado. Saida bruta: ' + limpo.slice(0, 400),
    encaminhar: 'suporte tecnico N1'
  };
}

dados.sla_horas = parseInt(dados.sla_horas, 10) || null;

return [{ json: dados }];

